package com.hagglehelper;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class HaggleHelperPluginTest
{
	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(HaggleHelperPlugin.class);
		RuneLite.main(args);
	}
}

package com.hagglehelper;

import lombok.Getter;

@Getter
public class TrackedItem
{
	private final int itemId;
	private final String name;
	private final int cost;
	private final int value;

	public TrackedItem(int itemId, String name, int cost, int value)
	{
		this.itemId = itemId;
		this.name = name;
		this.cost = cost;
		this.value = value;
	}

}

package com.hagglehelper;

import com.google.inject.Inject;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.CardLayout;
import java.awt.event.ActionEvent;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.KeyEvent;
import java.util.List;

import javax.swing.AbstractAction;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.item.ItemPrice;


@Slf4j
public class HaggleHelperPanel extends PluginPanel
{
	private static final int ROW_HEIGHT = 40;
	private final JTextField searchField = new JTextField();
	private final JTextField costField = new JTextField();
	private final JButton addButton = new JButton("Add / Update");
	private final JButton removeAllButton = new JButton("Remove All");
	private final JButton updateAllButton = new JButton("Update All");
	private final JLabel searchFeedbackLabel = new JLabel("");
	private final JLabel costFeedbackLabel = new JLabel("");
	private final JPanel listPanel = new JPanel();

	@Inject
	private ItemManager itemManager;

	@Inject
	private TrackedItemsManager trackedItemsManager;

	@Inject
	private HighlightedItemsManager highlightedItemsManager;

	@Inject
	private HaggleHelperConfig config;

	@Inject
	private ClientThread clientThread;

	private int resolvedItemId = -1;
	private String resolvedItemName = "";

	@Inject
	public HaggleHelperPanel()
	{
		super(false);

		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				onSearchChanged();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				onSearchChanged();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				onSearchChanged();
			}
		});

		searchField.addActionListener(e -> onAddClicked());
		addButton.addActionListener(e -> onAddClicked());
		costField.addActionListener(e -> onAddClicked());

		removeAllButton.addActionListener(e ->
		{
			int result = JOptionPane.showConfirmDialog(
				SwingUtilities.getWindowAncestor(this),
				"Are you sure you want to remove all tracked items?",
				"Confirm removal",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE
			);

			if (result == JOptionPane.YES_OPTION)
			{
				clientThread.invoke(() ->
				{
					trackedItemsManager.removeAllItems();
					SwingUtilities.invokeLater(this::refreshList);
				});
			}
		});

		updateAllButton.addActionListener(e ->
		{
			int result = JOptionPane.showConfirmDialog(
				SwingUtilities.getWindowAncestor(this),
				"Are you sure you want to update the cost of all tracked items?",
				"Confirm update",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE
			);

			if (result == JOptionPane.YES_OPTION)
			{
				clientThread.invoke(() ->
				{
					for (TrackedItem item : trackedItemsManager.getTrackedItems())
					{
						trackedItemsManager.setCost(
							item.getItemId(),
							item.getName(),
							itemManager.getItemPrice(item.getItemId())
						);
					}
					SwingUtilities.invokeLater(this::refreshList);
				});
			}
		});
	}

	public void init()
	{
		removeAll();

		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel(String.format(
			"<html><body style = 'color:white'>Haggle Helper <span style = 'color:#a5a5a5'>v%s</span></body></html>",
			HaggleHelperPlugin.getVersion()));
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
		title.setForeground(Color.WHITE);
		title.setBorder(new EmptyBorder(0, 0, 4, 0));
		add(title, BorderLayout.NORTH);

		JPanel centre = new JPanel(new BorderLayout(0, 8));
		centre.setBackground(ColorScheme.DARK_GRAY_COLOR);
		centre.add(buildAddForm(), BorderLayout.NORTH);
		centre.add(buildListSection(), BorderLayout.CENTER);
		add(centre, BorderLayout.CENTER);

		JPanel footer = new JPanel(new BorderLayout(0, 8));
		footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		footer.add(buildFooter(), BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);

		refreshList();
		revalidate();
		repaint();
	}

	public void deinit()
	{
	}

	private JPanel buildFooter()
	{
		JPanel panel = new JPanel(new GridBagLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(8, 8, 8, 8))
		);

		buildButton(removeAllButton, "icons/delete.png", "Removes all tracked items");
		buildButton(updateAllButton, "icons/balance.png",
			"Updates all costs from current Grand Exchange prices");

		GridBagConstraints gbc = new GridBagConstraints();

		gbc.insets = new Insets(0, 4, 0, 4);
		panel.add(updateAllButton, gbc);

		gbc.gridx = 1;
		panel.add(removeAllButton, gbc);

		return panel;
	}

	private JPanel buildAddForm()
	{
		JPanel panel = new JPanel(new GridBagLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(8, 8, 8, 8))
		);

		GridBagConstraints c = new GridBagConstraints();
		c.fill = GridBagConstraints.HORIZONTAL;
		c.insets = new Insets(2, 2, 2, 2);

		// Row 0: section label
		c.gridx = 0;
		c.gridy = 0;
		c.gridwidth = 2;
		c.weightx = 1;
		JLabel sectionLabel = new JLabel("Add an item:");
		sectionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		sectionLabel.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		panel.add(sectionLabel, c);

		// Row 1: search field
		c.gridy = 1;
		c.gridwidth = 2;
		searchField.setToolTipText("Enter item name");
		searchField.putClientProperty("JTextField.placeholderText", "Enter item name...");
		searchField.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		searchField.setForeground(Color.WHITE);
		searchField.setCaretColor(Color.WHITE);
		searchField.setBorder(new EmptyBorder(4, 6, 4, 6));
		panel.add(searchField, c);

		// Row 2: search feedback label
		c.gridy = 2;
		searchFeedbackLabel.setFont(FontManager.getRunescapeSmallFont());
		searchFeedbackLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(searchFeedbackLabel, c);

		// Row 3: cost label + field
		c.gridy = 3;
		c.gridwidth = 1;
		c.weightx = 0;
		JLabel costLabel = new JLabel("Cost (gp):");
		costLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		costLabel.setFont(FontManager.getRunescapeSmallFont());
		panel.add(costLabel, c);

		c.gridx = 1;
		c.weightx = 1;
		costField.setToolTipText("Enter item cost in gp");
		costField.putClientProperty("JTextField.placeholderText", "Enter item cost...");
		costField.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		costField.setForeground(Color.WHITE);
		costField.setCaretColor(Color.WHITE);
		costField.setBorder(new EmptyBorder(4, 6, 4, 6));
		panel.add(costField, c);

		// Row 4: cost feedback label
		c.gridx = 0;
		c.gridy = 4;
		c.weightx = 0;
		c.gridwidth = 2;
		costFeedbackLabel.setFont(FontManager.getRunescapeSmallFont());
		costFeedbackLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(costFeedbackLabel, c);

		// Row 5: add button
		c.gridy = 5;
		c.weightx = 1;
		buildButton(addButton, "icons/post_add.png", "Add or update a tracked item");
		panel.add(addButton, c);

		return panel;
	}

	private void buildButton(JButton button, String iconPath, String tooltip)
	{
		button.setBackground(ColorScheme.BRAND_ORANGE);
		button.setForeground(Color.WHITE);
		button.setFocusPainted(false);
		button.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		button.setBorder(new EmptyBorder(6, 10, 6, 10));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setIcon(new ImageIcon(ImageUtil.loadImageResource(getClass(), iconPath)));
		button.setToolTipText(tooltip);

	}

	private void buildSmallButton(JButton button, String iconPath, String tooltip)
	{
		button.setIcon(new ImageIcon(ImageUtil.loadImageResource(getClass(), iconPath)));
		button.setToolTipText(tooltip);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setBorderPainted(false);
		button.setFocusPainted(false);
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setBorder(new EmptyBorder(2, 4, 2, 4));
	}

	private JScrollPane buildListSection()
	{
		listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JScrollPane scroll = new JScrollPane(listPanel);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		scroll.setPreferredSize(new Dimension(0, 300));
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);

		return scroll;
	}

	private void onSearchChanged()
	{
		resolvedItemId = -1;
		resolvedItemName = "";
		searchFeedbackLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		searchFeedbackLabel.setText("");

		String text = searchField.getText().trim();
		if (text.isEmpty())
		{
			return;
		}

		List<ItemPrice> result = itemManager.search(text);
		if (result.size() == 1)
		{
			handleItemResolved(result.get(0));
		}
		else if (result.size() > 1)
		{
			for (ItemPrice item : result)
			{
				if (item.getName().equalsIgnoreCase(text))
				{
					handleItemResolved(item);
					return;
				}
			}
		}
		else
		{
			searchFeedbackLabel.setForeground(new Color(220, 50, 50));
			searchFeedbackLabel.setText("✗ No matches found");
		}
	}

	private void handleItemResolved(ItemPrice item)
	{
		resolvedItemId = item.getId();
		resolvedItemName = item.getName();
		searchFeedbackLabel.setForeground(new Color(0, 200, 80));
		searchFeedbackLabel.setText("✔ " + resolvedItemName);

		if (config.autoCost())
		{
			costField.setText(String.valueOf(item.getWikiPrice()));
		}
	}

	private void onAddClicked()
	{
		// Validate item
		if (resolvedItemId < 0)
		{
			costFeedbackLabel.setText("");
			searchFeedbackLabel.setForeground(new Color(220, 50, 50));
			searchFeedbackLabel.setText("✗ Enter a valid item name");
			return;
		}

		// Validate cost
		int cost;
		try
		{
			String raw = costField.getText().trim().replace(",", "");
			cost = Integer.parseInt(raw);
			if (cost < 0)
			{
				throw new NumberFormatException();
			}
		}
		catch (NumberFormatException e)
		{
			costFeedbackLabel.setForeground(new Color(220, 50, 50));
			costFeedbackLabel.setText("✗ Enter a valid cost ≥ 0");
			return;
		}

		clientThread.invoke(() ->
		{
			trackedItemsManager.setCost(resolvedItemId, resolvedItemName, cost);
			SwingUtilities.invokeLater(() ->
			{
				searchFeedbackLabel.setForeground(new Color(0, 200, 80));
				costFeedbackLabel.setForeground(new Color(0, 200, 80));
				costFeedbackLabel.setText("");
				searchField.setText("");
				costField.setText("");
				resolvedItemId = -1;
				resolvedItemName = "";
				refreshList();
				SwingUtilities.invokeLater(searchField::requestFocusInWindow);
			});
		});

	}

	void refreshList()
	{
		clientThread.invoke(() ->
		{
			TrackedItem[] items = trackedItemsManager.getTrackedItems();
			SwingUtilities.invokeLater(() ->
			{
				listPanel.removeAll();

				if (items.length == 0)
				{
					JLabel icon = new JLabel(new ImageIcon(
						ImageUtil.loadImageResource(getClass(), "icons/search_off.png")
					));
					icon.setAlignmentX(Component.CENTER_ALIGNMENT);

					JLabel empty = new JLabel("No items added yet.");
					empty.setAlignmentX(Component.CENTER_ALIGNMENT);
					empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
					empty.setFont(FontManager.getRunescapeSmallFont());

					listPanel.add(Box.createVerticalStrut(16));
					listPanel.add(icon);
					listPanel.add(Box.createVerticalStrut(16));
					listPanel.add(empty);
				}
				else
				{
					for (TrackedItem ti : items)
					{
						listPanel.add(buildItemRow(ti));
					}
				}

				listPanel.revalidate();
				listPanel.repaint();
				highlightedItemsManager.clear();
			});
		});
	}

	private JPanel buildItemRow(TrackedItem ti)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			new EmptyBorder(4, 6, 4, 6))
		);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));

		// Item icon
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		AsyncBufferedImage img = itemManager.getImage(ti.getItemId());
		img.addTo(icon);
		row.add(icon, BorderLayout.WEST);

		// Centre: name + cost
		JPanel centre = new JPanel();
		centre.setLayout(new BoxLayout(centre, BoxLayout.Y_AXIS));
		centre.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel nameLabel = new JLabel(ti.getName());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		centre.add(nameLabel);

		// Cost display/editor
		CardLayout cardLayout = new CardLayout();
		JPanel costPanel = new JPanel(cardLayout);
		costPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel costLabel = new JLabel(
			"Cost: " + HaggleHelperPlugin.formatGp(ti.getCost()) + " gp");
		costLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		costLabel.setFont(FontManager.getRunescapeSmallFont());

		// Editor
		JTextField costEditor = new JTextField(String.valueOf(ti.getCost()));
		costEditor.setFont(FontManager.getRunescapeSmallFont());
		costEditor.setForeground(Color.WHITE);
		costEditor.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		costEditor.setCaretColor(Color.WHITE);
		costEditor.setBorder(BorderFactory.createEmptyBorder());
		costEditor.setOpaque(false);

		JLabel costPrefix = new JLabel("Cost: ");
		costPrefix.setFont(FontManager.getRunescapeSmallFont());
		costPrefix.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JLabel gpSuffix = new JLabel(" gp");
		gpSuffix.setFont(FontManager.getRunescapeSmallFont());
		gpSuffix.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel editorPanel = new JPanel();
		editorPanel.setLayout(new BoxLayout(editorPanel, BoxLayout.X_AXIS));
		editorPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		editorPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

		editorPanel.add(costPrefix);
		editorPanel.add(costEditor);
		editorPanel.add(gpSuffix);

		editorPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			editorPanel.getPreferredSize().height));

		costPanel.add(costLabel, "label");
		costPanel.add(editorPanel, "editor");
		cardLayout.show(costPanel, "label");

		costPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		centre.add(costPanel);

		row.add(centre, BorderLayout.CENTER);

		Runnable resizeEditor = () ->
		{
			String text = costEditor.getText();
			if (text.isEmpty())
			{
				text = "0";
			}

			FontMetrics fm = costEditor.getFontMetrics(costEditor.getFont());

			int width = fm.stringWidth(text) + 1;
			int height = costEditor.getPreferredSize().height;

			Dimension size = new Dimension(width, height);

			costEditor.setPreferredSize(size);
			costEditor.setMaximumSize(size);
			costEditor.setMinimumSize(size);

			editorPanel.revalidate();
			editorPanel.repaint();
		};

		resizeEditor.run();

		costEditor.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				resizeEditor.run();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				resizeEditor.run();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				resizeEditor.run();
			}
		});

		Runnable cancelEdit = () ->
		{
			costEditor.setText(String.valueOf(ti.getCost()));
			resizeEditor.run();
			cardLayout.show(costPanel, "label");
		};

		Runnable commitEdit = () ->
		{
			try
			{
				int newCost = Integer.parseInt(
					costEditor.getText().replace(",", "").trim());

				if (newCost < 0)
				{
					throw new NumberFormatException();
				}

				clientThread.invoke(() ->
				{
					trackedItemsManager.setCost(
						ti.getItemId(),
						ti.getName(),
						newCost
					);

					SwingUtilities.invokeLater(this::refreshList);
				});
			}
			catch (NumberFormatException ignored)
			{
				cancelEdit.run();
			}
		};

		// Save on Enter
		costEditor.addActionListener(e -> commitEdit.run());

		// Save when focus lost
		costEditor.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				commitEdit.run();
			}
		});

		// Cancel on Esc
		costEditor.getInputMap().put(
			KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0),
			"cancel"
		);

		costEditor.getActionMap().put("cancel", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				cancelEdit.run();
			}
		});

		// Buttons
		JPanel buttons = new JPanel(new GridLayout(1, 2));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JButton edit = new JButton();
		buildSmallButton(edit, "icons/edit.png", "Edit cost of this tracked item");
		edit.addActionListener(e ->
		{
			costEditor.setText(String.valueOf(ti.getCost()));
			resizeEditor.run();

			cardLayout.show(costPanel, "editor");
			costEditor.requestFocusInWindow();
			costEditor.selectAll();
		});
		buttons.add(edit);

		JButton update = new JButton();
		buildSmallButton(update, "icons/balance.png", "Update cost from Grand Exchange price");
		update.addActionListener(e ->
		{
			clientThread.invoke(() ->
			{
				trackedItemsManager.setCost(
					ti.getItemId(),
					ti.getName(),
					itemManager.getItemPrice(ti.getItemId())
				);
				SwingUtilities.invokeLater(this::refreshList);
			});
		});
		buttons.add(update);

		JButton remove = new JButton();
		buildSmallButton(remove, "icons/delete.png", "Remove this tracked item");
		remove.addActionListener(e ->
		{
			clientThread.invoke(() ->
			{
				trackedItemsManager.removeItem(ti.getItemId());
				SwingUtilities.invokeLater(this::refreshList);
			});
		});
		buttons.add(remove);

		row.add(buttons, BorderLayout.EAST);

		return row;
	}
}

package com.hagglehelper;

