import net.runelite.client.util.LinkBrowser;

@Slf4j
public class ErrorPopups
{
	@Inject
	HaggleHelperPlugin plugin;

	@Inject
	Client client;

	@Inject
	ItemManager itemManager;

	private static final String GITHUB_ISSUE_URL = "https://github.com/gavin-lb/haggle-helper/issues/new";
	private static String BASE_REPORT;
	private static final String BASE_EXPLANATION = "Please help improve Haggle Helper by reporting this issue " +
		"on GitHub with the \"Open GitHub Issue\" button below. Alternatively, you can click \"Copy " +
		"Report\" and paste it into a new GitHub issue manually.";
	private static final String FOOTER = "(This popup can be disabled with the \"Error reports\" config option)";
	private static final ImmutableSet<Integer> ALI_JUNK = ImmutableSet.of(
		ItemID.BRONZE_PICKAXE,
		ItemID.BUCKET_EMPTY,
		ItemID.KNIFE,
		ItemID.RAW_CHICKEN,
		ItemID.TINDERBOX
	);

	ErrorPopups()
	{
		BASE_REPORT = String.format(
			"## Haggle Helper Bug Report%n%n" +
				" - **RuneLite version:** %s%n" +
				" - **Plugin version:** %s%n",
			RuneLiteProperties.getVersion(),
			HaggleHelperPlugin.getVersion()
		);
	}

	private void base(String extraReport, String name, String githubTitle)
	{
		final String report = BASE_REPORT + extraReport;
		final String explanation = "Haggle Helper has detected a " + name + "!\n\n" +
			BASE_EXPLANATION;

		SwingUtilities.invokeLater(() ->
		{
			JTextArea infoArea = new JTextArea(explanation);
			infoArea.setEditable(false);
			infoArea.setOpaque(false);
			infoArea.setLineWrap(true);
			infoArea.setWrapStyleWord(true);
			infoArea.setFocusable(false);
			infoArea.setBorder(BorderFactory.createEmptyBorder(5, 5, 10, 5));

			JTextArea reportArea = new JTextArea(report);
			reportArea.setEditable(false);
			reportArea.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 12));
			reportArea.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			reportArea.setLineWrap(true);
			reportArea.setWrapStyleWord(true);
			reportArea.setFocusable(true);

			JTextArea footerArea = new JTextArea(FOOTER);
			footerArea.setEditable(false);
			footerArea.setOpaque(false);
			footerArea.setLineWrap(true);
			footerArea.setWrapStyleWord(true);
			footerArea.setFocusable(false);
			footerArea.setBorder(BorderFactory.createEmptyBorder(10, 10, 20, 10));

			JDialog dialog = new JDialog((Frame) null, "Haggle Helper - " + name, false);

			JButton copyButton = new JButton("Copy Report");
			copyButton.addActionListener(e ->
			{
				Toolkit.getDefaultToolkit().getSystemClipboard().setContents(
					new StringSelection(report), null);
				dialog.dispose();
			});

			String issueUrl = GITHUB_ISSUE_URL +
				"?title=" + URLEncoder.encode(
					githubTitle,
					StandardCharsets.UTF_8
				) +
				"&body=" + URLEncoder.encode(
					report,
					StandardCharsets.UTF_8
				);

			JButton githubButton = new JButton("Open GitHub Issue");
			githubButton.setBackground(ColorScheme.BRAND_ORANGE);
			githubButton.setForeground(ColorScheme.DARK_GRAY_COLOR);
			githubButton.addActionListener(e ->
			{
				LinkBrowser.browse(issueUrl);
				dialog.dispose();
			});

			JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT));
			buttons.add(copyButton);
			buttons.add(githubButton);

			JPanel panel = new JPanel(new BorderLayout(0, 10));
			panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

			JScrollPane scrollPane = new JScrollPane(reportArea);

			scrollPane.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
			scrollPane.setPreferredSize(new Dimension(600, 250));

			JPanel southPanel = new JPanel(new BorderLayout());
			southPanel.add(footerArea, BorderLayout.NORTH);
			southPanel.add(buttons, BorderLayout.SOUTH);

			panel.add(infoArea, BorderLayout.NORTH);
			panel.add(scrollPane, BorderLayout.CENTER);
			panel.add(southPanel, BorderLayout.SOUTH);

			URL iconUrl = getClass().getResource("/com/hagglehelper/icons/icon.png");
			if (iconUrl != null)
			{
				dialog.setIconImage(new ImageIcon(iconUrl).getImage());
			}

			dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
			dialog.setContentPane(panel);
			dialog.pack();
			dialog.setMinimumSize(new Dimension(400, 300));
			dialog.setLocationRelativeTo(client.getCanvas());
			dialog.setVisible(true);
		});
	}

	public void tradeMismatch(Map<Integer, Integer> delta, int expected, int observed)
	{
		// Ali Morrisane will forcibly sell the player random junk 
		// See: https://oldschool.runescape.wiki/w/Ali%27s_Discount_Wares.#Junk
		if (plugin.shop.name.contains("Ali's Discount Wares.(general)") &&
			observed == -10 && delta.size() == 1 &&
			ALI_JUNK.contains(delta.keySet().iterator().next()))
		{
			log.debug("Ali's random junk, ignoring trade mismatch");
			return;
		}

		final String name = "Trade Mismatch";

		final String report = String.format(
			" - **Type:** %s%n" +
				"--- %n" +
				" - **Shop name:** %s%n" +
				" - **Shop ID:** %s%n" +
				" - **Shop data:** %s%n" +
				" - **Inventory delta:** %s%n" +
				" - **Expected revenue:** %d%n" +
				" - **Observed revenue:** %d%n",
			name,
			plugin.shop.name,
			plugin.shop.containerId,
			plugin.shop,
			delta.keySet().stream().collect(Collectors.toMap(
				itemId -> String.format(
					"\"%s\"",
					itemManager.getItemComposition(itemId).getName()
				),
				itemId -> String.format(
					"Item(quantity=%d, itemId=%d)",
					delta.get(itemId),
					itemId
				)
			)).toString(),
			expected,
			observed
		);

		final String githubTitle = String.format(
			"[%s] %s",
			name, plugin.shop.name
		);
		base(report, name, githubTitle);
	}

	public void priceMismatch(HighlightedItem item, String itemName, int value, int price, String mode)
	{
		final String name = "Price Mismatch";

		final int stock = plugin.shop.getStock(item.id);
		final String report = String.format(
			" - **Type:** %s%n" +
				"--- %n" +
				" - **Item name:** %s%n" +
				" - **Item ID:** %d%n" +
				" - **Shop name:** %s%n" +
				" - **Shop ID:** %d%n" +
				" - **Mode:** %s%n" +
				" - **Current stock:** %d%n" +
				" - **Expected price:** %d%n" +
				" - **Observed value:** %d%n",
			name,
			itemName,
			item.id,
			plugin.shop.name,
			plugin.shop.containerId,
			mode,
			stock,
			price,
			value
		);

		final String githubTitle = String.format(
			"[%s] \"%s\" %s \"%s\"",
			name, itemName, mode, plugin.shop.name
		);

		// Check if stock is unchanged after short delay to not false positive when value + sell is spammed
		Timer timer = new Timer(100, e ->
		{
			int newStock = plugin.shop.getStock(item.id);
			if (newStock == stock)
			{
				base(report, name, githubTitle);
			}
			else
			{
				log.debug(
					"Stock changed - cancelling price mismatch error popup, oldStock={} newStock={}",
					stock, newStock
				);
			}
		});
		timer.setRepeats(false);
		timer.start();
	}

	public void unknownShop(int containerId, String shopName, Item[] items)
	{
		final String name = "Unknown Shop";

		final String report = String.format(
			" - **Type:** %s%n" +
				"--- %n" +
				" - **Shop name:** %s%n" +
				" - **Shop ID:** %d%n" +
				" - **Items:** %s%n",
			name,
			shopName,
			containerId,
			Arrays.stream(items).collect(Collectors.toMap(
				item -> String.format(
					"\"%s\"",
					itemManager.getItemComposition(item.getId()).getName()
				),
				item -> item.toString()
			)));


		final String githubTitle = String.format(
			"[%s] \"%s\"",
			name, shopName
		);

		base(report, name, githubTitle);
	}
}

package com.hagglehelper;

import com.google.inject.Inject;
import com.hagglehelper.HaggleHelperConfig.InterfaceMode;
import com.hagglehelper.HaggleHelperConfig.OverlayMode;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

@Slf4j
public class HaggleHelperOverlay extends Overlay
{
	@Inject
	private Client client;

	@Inject
	private HaggleHelperConfig config;

	@Inject
	private HaggleHelperPlugin plugin;

	@Inject
	private HighlightedItemsManager highlightedItemsManager;

	@Inject
	private TrackedItemsManager trackedItemsManager;

	@Inject
	private TooltipManager tooltipManager;

	@Inject
	private ItemManager itemManager;

	public HaggleHelperOverlay()
	{
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Widget items = client.getWidget(InterfaceID.Shopside.ITEMS);
		final Widget shopItems = client.getWidget(InterfaceID.Shopmain.ITEMS);
		if (items == null || shopItems == null)
		{
			return null;
		}

		final Widget[] itemWidgets = items.getChildren();
		final Widget[] shopItemWidgets = shopItems.getChildren();
		if (itemWidgets == null || shopItemWidgets == null)
		{
			return null;
		}

		if (config.overlayEnabled() != OverlayMode.NONE)
		{
			InterfaceMode mode = config.interfaceMode();

			if (mode.showInventory())
			{
				drawItemOverlay(graphics, itemWidgets, InterfaceMode.INVENTORY);
			}

			if (mode.showShop())
			{
				drawItemOverlay(graphics, shopItemWidgets, InterfaceMode.SHOP);
			}
		}

		if (config.tooltipEnabled() != OverlayMode.NONE)
		{
			drawTooltip();
		}

		return null;
	}

	private void drawItemOverlay(Graphics2D graphics, Widget[] items, InterfaceMode mode)
	{
		FontMetrics fm = graphics.getFontMetrics();
		for (Widget itemWidget : items)
		{
			if (itemWidget == null)
			{
				continue;
			}

			int itemId = itemWidget.getItemId();
			if (itemId <= 0)
			{
				continue;
			}

			if (config.overlayEnabled() == OverlayMode.TRACKED && !trackedItemsManager
				.isTrackedItemId(itemId))
			{
				continue;
			}

			if (itemId == ItemID.COINS || itemId == ItemID.PLATINUM || itemId == ItemID.BLANKOBJECT)
			{
				continue;
			}

			if (!plugin.shop.isTradableWith(itemId))
			{
				continue;
			}

			if (mode == InterfaceMode.INVENTORY && !itemManager.getItemComposition(itemId)
				.isTradeable())
			{
				continue;
			}

			HighlightedItem highlightedItem = highlightedItemsManager.getOrCreate(itemId, mode);

			final Rectangle bounds = new Rectangle(itemWidget.getBounds());
			if (bounds.x < 0 || bounds.y < 0)
			{
				continue;
			}

			Dimension padding = config.boxPadding();
			bounds.grow(padding.width, padding.height);

			Dimension offset = config.boxOffset();
			bounds.translate(offset.width - 2, offset.height - 2);

			Color color = highlightedItem.color;
			if (config.showBoxFill())
			{
				graphics.setColor(color);
				graphics.fill(bounds);
			}

			if (config.showBoxBorder())
			{
				graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue()));
				graphics.draw(bounds);
			}

			if (config.showCurrentPrice())
			{
				final String currentPriceText = config.shortenCurrentPrice()
					? formatGp(highlightedItem.currentPrice)
					: String.valueOf(highlightedItem.currentPrice);

				Dimension currentPriceOffset = config.currentPriceOffset();
				OverlayUtil.renderTextLocation(graphics, new Point(bounds.x +
					currentPriceOffset.width - fm.stringWidth(currentPriceText), bounds.y +
						currentPriceOffset.height), currentPriceText, config.currentPriceColor());
			}

			if (highlightedItem.maxProfit > config.profitThreshold())
			{
				if (config.showNumber())
				{
					Dimension numberOffset = config.numberOffset();
					OverlayUtil.renderTextLocation(graphics, new Point(bounds.x +
						numberOffset.width, bounds.y + numberOffset.height), String.valueOf(
							highlightedItem.numProfitable), config.numberColor());
				}

				if (config.showProfit())
				{
					final String profitText = config.shortenProfit()
						? formatGp(highlightedItem.maxProfit)
						: String.valueOf(highlightedItem.maxProfit);

					Dimension profitOffset = config.profitOffset();

					OverlayUtil.renderTextLocation(graphics, new Point(bounds.x +
						profitOffset.width - fm.stringWidth(profitText), bounds.y +
							profitOffset.height), profitText, config.profitColor());
				}
			}
		}
	}

	private String formatGp(int gp)
	{
		return gp >= 1_000 ? String.format("%.1fK", gp / 1000.0) : String.valueOf(gp);
	}

	private void drawTooltip()
	{
		if (client.isMenuOpen())
		{
			return;
		}

		MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
		final int last = menuEntries.length - 1;
		if (last < 0)
		{
			return;
		}

		MenuEntry menuEntry = menuEntries[last];
		final int itemId = menuEntry.getItemId();
		if (itemId <= 0 || config.tooltipEnabled() == OverlayMode.TRACKED && !trackedItemsManager
			.isTrackedItemId(itemId))
		{
			return;
		}

		if (!plugin.shop.isTradableWith(itemId))
		{
			return;
		}

		Widget widget = menuEntry.getWidget();
		if (widget == null)
		{
			return;
		}

		InterfaceMode mode = widget.getId() == InterfaceID.Shopmain.ITEMS
			? InterfaceMode.SHOP
			: InterfaceMode.INVENTORY;
		if (mode != config.interfaceMode() && config.interfaceMode() != InterfaceMode.BOTH)
		{
			return;
		}

		HighlightedItem item = highlightedItemsManager.getOrCreate(itemId, mode);
		if (item == null)
		{
			return;
		}

		String menuOption = menuEntry.getOption().replaceAll("<.*>", "");
		final int transactionAmount;
		try
		{
			transactionAmount = Integer.parseInt(menuOption.replaceAll("\\D", ""));
		}
		catch (NumberFormatException e)
		{
			return;
		}

		final int stockAmount;
		final int amount;
		final int profit;
		final int revenue;
		if (item.mode == InterfaceMode.INVENTORY)
		{
			stockAmount = widget.getItemQuantity();
			amount = Math.min(transactionAmount, stockAmount);
			profit = plugin.shop.getProfitSellTo(amount, item);
			revenue = plugin.shop.getRevenueSellTo(amount, item);
		}
		else
		{
			stockAmount = plugin.shop.getStock(item);
			amount = Math.min(transactionAmount, stockAmount);
			profit = plugin.shop.getProfitBuyFrom(amount, item);
			revenue = plugin.shop.getRevenueBuyFrom(amount, item);
		}

		final int profitThreshold = config.profitThreshold();
		final int bulkLossAllowance = config.bulkLossAllowance();

		final int loss = profit > profitThreshold && transactionAmount > item.numProfitable
			? item.maxProfit - profit
			: 0;

		final String option = transactionAmount != amount
			? String.format("%s <col=ff0000>(%d)</col>", menuOption, amount)
			: menuOption;

		final String profitColor = profit <= transactionAmount * profitThreshold
			? "ff0000"
			: "ffff00";

		final String lossColor = loss > bulkLossAllowance ? "ff0000" : "ffff00";

		final String lossText = loss > 0
			? String.format("<col=%s>(-%,d gp)</col>", lossColor, loss)
			: "";

		final String noun = item.mode == InterfaceMode.SHOP ? "cost" : "value";

		tooltipManager.add(new Tooltip(String.format(
			"%s %s: <col=ffff00>%,d gp</col><br>%s profit: <col=%s>%,d gp</col> %s", option, noun,
			revenue, option, profitColor, profit, lossText)));
	}
}

package com.hagglehelper;

import com.google.common.collect.ImmutableMap;
import com.hagglehelper.HaggleHelperConfig.InterfaceMode;
import java.awt.Color;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;

import lombok.ToString;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;

@Slf4j
@ToString
public class Shop
{
	private static final int SELL_TO_FLOOR = 10;
	private static final Map<Integer, Integer> FIXED_BUY_FROM_PRICE = ImmutableMap
		.<Integer, Integer>builder()
		.put(981, 21000)
		.put(21354, 1)
		.put(11705, 75)
		.put(11706, 75)
		.build();

	@ToString.Exclude
	@Inject
	private transient HaggleHelperConfig config;

	@ToString.Exclude
	@Inject
	private transient TrackedItemsManager trackedItemsManager;

	@ToString.Exclude
	@Inject
	private transient Map<Integer, Integer> inventoryMap;

	@ToString.Exclude
	@Inject
	private transient boolean lumbridgeElite;

	String name;
	int containerId;
	int sellsAt;
	int buysAt;
	float changePer;
	Map<Integer, Integer> defaultStocks;
	Map<Integer, Integer> currentStocks;
	boolean isGeneral;
	final Map<Integer, Integer> queue = new HashMap<>();

	/*
	Have to apply Lumbridge Elite manually like this because Jagex messed up the implementation.

	Wiki data is incorrect because the rounding is reversed, eg. 145.6 rounds up to 146
	instead of down (or, more precisely, truncating towards zero) to 145 like it ought to 
	due to integer division. This is due to the way they are calculating the discounted price. 
	Rather than calculating 80% of the normal price (ie. setting the sellsAt to 104% from the 
	regular 130%), they first calculate 20% of the normal cost, which gets *rounded down* during 
	the integer division, then they *subtract* it from the cost; resulting in the final price 
	being effectively *rounded up*.

	For example, "Empty jug pack" has an item value of 140 gp. Hence, the usual 130% sellsAt 
	chest sells (full stock) for 140 * 1.3 = 182 gp. However, a 20% discount should result
	in a price of 182 * 0.8 = 145.6 or equivalently 140 * 1.04 = 145.6, which should get 
	rounded down during integer division to 145 gp. This is the price the wiki lists, but
	the price in game is actually 146 gp, because Jagex actually calculates it like this:
	182 * 0.2 = 36.4, which gets rounded down due to integer division to 36, then they 
	subtract it to give 182 - 36 = 146 gp, essentially resulting in the final price having
	been erroneously rounded up. 
	*/
	private int applyLumbridgeEliteDiscount(int price)
	{
		if (lumbridgeElite && name.contains("Culinaromancer"))
		{
			price -= price * 20 / 100;
		}
		return price;
	}

	public int getStock(int itemId)
	{
		return currentStocks != null
			? currentStocks.getOrDefault(itemId, 0) + queue.getOrDefault(itemId, 0)
			: 0;
	}

	public int getStock(HighlightedItem item)
	{
		return getStock(item.id);
	}

	@SuppressWarnings("null")
	public boolean updateStock(Item[] items, int containerId)
	{
		this.containerId = containerId;
		log.debug("Updating items={} on shop={}", items, this);
		Map<Integer, Integer> newStocks = Arrays.stream(items)
			.filter(item -> item.getId() > 0)
			.collect(Collectors.toMap(Item::getId, Item::getQuantity));

		if (newStocks.equals(currentStocks))
		{
			log.debug("Stock unchanged");
			return false;
		}

		if (currentStocks != null && !queue.isEmpty())
		{
			for (Item item : items)
			{
				int itemId = item.getId();
				int queued = queue.getOrDefault(itemId, 0);
				if (queued != 0)
				{
					int previousStock = currentStocks.getOrDefault(itemId, 0);
					int newStock = newStocks.get(itemId);
					log.debug("queued item, queued={} previousStock={} currentStock={}", queued,
						previousStock, newStock);

					int newQueued = queued - newStock + previousStock;
					if (newQueued != 0)
					{
						queue.put(itemId, newQueued);
						log.debug("newQueued={}", newQueued);
					}
					else
					{
						queue.remove(itemId);
						log.debug("removed queued");
					}
				}
			}
		}

		currentStocks = newStocks;
		return true;
	}

	public int getStockDelta(int itemId, int currentStock)
	{
		int defaultStock = defaultStocks.getOrDefault(itemId, 0);
		return defaultStock - currentStock;
	}

	public int getStockDelta(int itemId)
	{
		return getStockDelta(itemId, getStock(itemId));
	}

	public int getStockDelta(HighlightedItem item)
	{
		return getStockDelta(item.id);
	}

	private int getItemPrice(int itemId, int itemValue, int multiplier)
	{
		int delta = getStockDelta(itemId);
		return (int) Math.floor(itemValue * (multiplier + delta * changePer) / 100);
	}

	public int getItemPrice(HighlightedItem item)
	{
		return item.mode == InterfaceMode.INVENTORY
			? getItemPriceSellTo(item.id, item.value)
			: getItemPriceBuyFrom(item.id, item.value);
	}

	public int getItemPriceSellTo(HighlightedItem item)
	{
		return getItemPriceSellTo(item.id, item.value);
	}

	public int getItemPriceSellTo(int itemId, int itemValue)
	{
		return Math.max(getItemPrice(itemId, itemValue, buysAt), SELL_TO_FLOOR * itemValue / 100);
	}

	public int getItemPriceBuyFrom(HighlightedItem item)
	{
		return getItemPriceBuyFrom(item.id, item.value);
	}

	public int getItemPriceBuyFrom(int itemId, int itemValue)
	{
		if (FIXED_BUY_FROM_PRICE.containsKey(itemId))
		{
			return FIXED_BUY_FROM_PRICE.get(itemId);
		}
		return Math.max(1, applyLumbridgeEliteDiscount(
			Math.max(getItemPrice(itemId, itemValue, sellsAt), (sellsAt - 100) * itemValue / 100)
		));
	}

	public int getNumProfitableSellTo(int itemId, int cost, int itemValue)
	{
		if (changePer == 0)
		{
			return getItemPriceSellTo(itemId, itemValue) > cost + config.profitThreshold()
				? inventoryMap.getOrDefault(itemId, 0)
				: 0;
		}

		float percent = 100f * (cost + config.profitThreshold()) / itemValue;
		float num = (buysAt - percent) / changePer;
		return Math.max(0, (int) Math.ceil(num) + getStockDelta(itemId));
	}

	public int getNumProfitableSellTo(HighlightedItem item)
	{
		return getNumProfitableSellTo(item.id, item.cost, item.value);
	}

	public int getNumProfitableBuyFrom(int itemId, int cost, int itemValue)
	{
		if (FIXED_BUY_FROM_PRICE.containsKey(itemId))
		{
			return 0;
		}

		if (changePer == 0)
		{
			return getItemPriceBuyFrom(itemId, itemValue) + config.profitThreshold() < cost
				? getStock(itemId)
				: 0;
		}

		int lumbModifier = lumbridgeElite && name.contains("Culinaromancer")
			? 20
			: 0;

		float percent = 100f * (cost - config.profitThreshold()) / itemValue;
		float num = (percent - sellsAt + lumbModifier) / changePer;
		int adjustedNum = Math.max(0, (int) Math.ceil(num) - getStockDelta(itemId));
		return Math.min(getStock(itemId), adjustedNum);
	}

	public int getNumProfitableBuyFrom(HighlightedItem item)
	{
		return getNumProfitableBuyFrom(item.id, item.cost, item.value);
	}

	public int getTotalProfitSellTo(int itemId, int cost, int itemValue)
	{
		int num = getNumProfitableSellTo(itemId, cost, itemValue);
		return getProfitSellTo(num, itemId, cost, itemValue);
	}

	public int getTotalProfitSellTo(HighlightedItem item)
	{
		return getTotalProfitSellTo(item.id, item.cost, item.value);
	}

	public int getTotalProfitBuyFrom(int itemId, int cost, int itemValue)
	{
		int num = getNumProfitableBuyFrom(itemId, cost, itemValue);
		return getProfitBuyFrom(num, itemId, cost, itemValue);
	}

	public int getTotalProfitBuyFrom(HighlightedItem item)
	{
		return getTotalProfitBuyFrom(item.id, item.cost, item.value);
	}

	public int getRevenueBuyFrom(int quantity, HighlightedItem item)
	{
		return getRevenueBuyFrom(quantity, item.id, item.value);
	}

	public int getRevenueBuyFrom(int quantity, int itemId, int itemValue)
	{
		return getRevenueBuyFrom(quantity, itemId, itemValue, getStock(itemId));
	}

	public int getRevenueBuyFrom(int quantity, int itemId, int itemValue, int currentStock)
	{
		if (quantity <= 0)
		{
			return 0;
		}

		float pricePercent = sellsAt + changePer * getStockDelta(itemId, currentStock);
		int revenue = 0;
		for (int i = 0; i < quantity; i++, pricePercent += changePer)
		{
			revenue += FIXED_BUY_FROM_PRICE.containsKey(itemId)
				? FIXED_BUY_FROM_PRICE.get(itemId)
				: Math.max(1, applyLumbridgeEliteDiscount(
					(int) Math.floor(Math.max(pricePercent, sellsAt - 100) * itemValue / 100)
				));
		}

		return revenue;
	}

	public int getRevenueSellTo(int quantity, HighlightedItem item)
	{
		return getRevenueSellTo(quantity, item.id, item.value);
	}

	public int getRevenueSellTo(int quantity, int itemId, int itemValue)
	{
		return getRevenueSellTo(quantity, itemId, itemValue, getStock(itemId));
	}

	public int getRevenueSellTo(int quantity, int itemId, int itemValue, int currentStock)
	{
		if (quantity <= 0)
		{
			return 0;
		}

		float pricePercent = buysAt + changePer * getStockDelta(itemId, currentStock);
		int revenue = 0;
		for (int i = 0; i < quantity; i++, pricePercent -= changePer)
		{
			revenue += (int) Math.floor(Math.max(pricePercent, SELL_TO_FLOOR) * itemValue / 100);
		}

		return revenue;
	}

	public int getProfitSellTo(int quantity, HighlightedItem item)
	{
		return getProfitSellTo(quantity, item.id, item.cost, item.value);
	}

	public int getProfitSellTo(int quantity, int itemId, int cost, int itemValue)
	{
		return quantity > 0 ? getRevenueSellTo(quantity, itemId, itemValue) - cost * quantity : 0;
	}

	public int getProfitBuyFrom(int quantity, HighlightedItem item)
	{
		return getProfitBuyFrom(quantity, item.id, item.cost, item.value);
	}

	public int getProfitBuyFrom(int quantity, int itemId, int cost, int itemValue)
	{
		return quantity > 0 ? cost * quantity - getRevenueBuyFrom(quantity, itemId, itemValue) : 0;
	}

	public Color getColorSellTo(HighlightedItem item)
	{
		return getColor(
			getProfitSellTo(1, item),
			getProfitSellTo(5, item),
			getProfitSellTo(10, item),
			getNumProfitableSellTo(item),
			getTotalProfitSellTo(item)
		);
	}

	public Color getColorBuyFrom(HighlightedItem item)
	{
		return getColor(
			getProfitBuyFrom(1, item),
			getProfitBuyFrom(5, item),
			getProfitBuyFrom(10, item),
			getNumProfitableBuyFrom(item),
			getTotalProfitBuyFrom(item)
		);
	}

	private Color getColor(int profit1, int profit5, int profit10, int numProfitable, int maxProfit)
	{
		int profitThreshold = config.profitThreshold();
		int bulkLossAllowance = config.bulkLossAllowance();

		if (maxProfit <= profitThreshold)
		{
			return config.unprofitableColor();
		}
		else if (profit10 > 10 * profitThreshold && profit10 > Math.max(profit5, profit1) &&
			(numProfitable >= 10 || maxProfit - profit10 < bulkLossAllowance))
		{
			return config.tenProfitableColor();
		}
		else if (profit5 > 5 * profitThreshold && profit5 > profit1 && (numProfitable >= 5 ||
			maxProfit - profit5 < bulkLossAllowance))
		{
			return config.fiveProfitableColor();
		}
		else
		{
			return config.oneProfitableColor();
		}
	}

	public boolean isTradableWith(int itemId)
	{
		int unnotedId = trackedItemsManager.getUnnotedId(itemId);
		return isGeneral || defaultStocks.containsKey(itemId) || currentStocks.containsKey(
			itemId) || defaultStocks.containsKey(unnotedId) || currentStocks.containsKey(unnotedId);
	}

	public boolean isTradableWith(HighlightedItem item)
	{
		return isTradableWith(item.id);
	}

	public Integer processTransaction(String menuOption, HighlightedItem item)
		throws UnprofitableTransactionException
	{
		if (!isTradableWith(item))
		{
			return null;
		}

		int amount = Integer.parseInt(menuOption.replaceAll("\\D", ""));
		if (item.mode == InterfaceMode.SHOP)
		{
			amount = Math.min(amount, getStock(item.id));
			int playerCoins = inventoryMap.getOrDefault(ItemID.COINS, 0);
			int cost = getRevenueBuyFrom(amount, item.id, item.value);
			if (cost > playerCoins)
			{

				for (int i = 0; i < amount; i++)
				{
					cost = getRevenueBuyFrom(i + 1, item.id, item.value);
					if (cost > playerCoins)
					{
						log.debug(
							"Not enough coins to buy, limiting purchase to: i={} amount={} cost={} playerCoins={} item={}",
							i, amount, cost, playerCoins, item);
						amount = i;
						break;
					}
				}
			}
		}
		else
		{
			amount = Math.min(amount, inventoryMap.getOrDefault(item.id, 0));
		}

		int profit = item.mode == InterfaceMode.INVENTORY
			? getProfitSellTo(amount, item)
			: getProfitBuyFrom(amount, item);
		int profitDelta = item.maxProfit - profit;

		int queued = queue.getOrDefault(item.id, 0);
		if (queued != 0)
		{
			log.debug("Transaction while queued, queued={} amount={} item={}", queued, amount,
				item);
		}

		if (profit > amount * config.profitThreshold() && (amount <= item.numProfitable ||
			profitDelta <= config.bulkLossAllowance()))
		{
			log.debug(
				"Allowing profitable transaction: amount={} queued={} profit={} profitDelta={} item={}",
				amount, queued, profit, profitDelta, item);

			queue.put(item.id, queued + (item.mode == InterfaceMode.INVENTORY
				? Math.min(amount, inventoryMap.get(item.id))
				: -Math.min(amount, getStock(item.id)))
			);

			item.numProfitable -= amount;
			item.maxProfit -= profit;
			item.currentPrice = getItemPrice(item);
			return profit;
		}

		log.debug("Blocked transaction: amount={} queued={} profit={} profitDelta={} item={}",
			amount, queued, profit, profitDelta, item);
		throw new UnprofitableTransactionException();
	}

	public static class UnprofitableTransactionException extends Exception
	{
	}
}

package com.hagglehelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;

import javax.inject.Inject;

import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class HaggleHelperOverlayPanel extends OverlayPanel
{
	@Inject
	private HaggleHelperConfig config;

	private Instant sessionStart;
	private int profit = 0;

	@Inject
	private HaggleHelperOverlayPanel()
	{
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(220, 0));

		getMenuEntries().add(
			new OverlayMenuEntry(
				MenuAction.RUNELITE_OVERLAY,
				"Reset",
				"Haggle Helper"
			)
		);
	}

	public void addProfit(Integer value)
	{
		if (value == null)
		{
			return;
		}

		profit += value;
		if (sessionStart == null)
		{
			sessionStart = Instant.now();
		}
	}

	public int getProfitPerHour()
	{
		if (sessionStart == null)
		{
			return 0;
		}

		long elapsedSeconds = Duration.between(sessionStart, Instant.now()).getSeconds();

		if (elapsedSeconds <= 0)
		{
			return 0;
		}

		return (int) ((long) profit * 3600 / elapsedSeconds);
	}

	public void resetProfit()
	{
		profit = 0;
		sessionStart = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.profitInfoEnabled())
		{
			return null;
		}

		if (profit == 0)
		{
			return null;
		}

		panelComponent.getChildren().clear();

		panelComponent.getChildren().add(
			TitleComponent.builder()
				.text("Haggle Helper")
				.build()
		);

		panelComponent.getChildren().add(
			LineComponent.builder()
				.left("Profit")
				.right(HaggleHelperPlugin.formatGp(profit) + " gp")
				.rightColor(
					profit > 10_000_000
						? Color.decode("#00ff84")
						: profit > 10_000 ? Color.WHITE : Color.YELLOW
				)
				.build()
		);

		final int profitPerHour = getProfitPerHour();
		panelComponent.getChildren().add(
			LineComponent.builder()
				.left("Profit/hr")
				.right(HaggleHelperPlugin.formatGp(profitPerHour) + " gp/hr")
				.rightColor(
					profitPerHour > 10_000_000
						? Color.decode("#00ff84")
						: profitPerHour > 10_000 ? Color.WHITE : Color.YELLOW
				)
				.build()
		);

		return super.render(graphics);
	}
}

